# Check conv3 biases for all neurons
conv3_bias = W['conv3.bias'].detach().cpu().numpy()
print("Conv3 biases:")
for i in range(64):
    if abs(conv3_bias[i]) > 0.3:
        print(f"  Neuron {i}: {conv3_bias[i]:.4f}")

# Check which neurons have positive corner response AND positive fc_weight for each class
# More systematically
fc_w = W['fc.weight'].detach().cpu().numpy()
conv3_w = W['conv3.weight'].detach().cpu().numpy()

corner_names = ['TL', 'TR', 'BL', 'BR']
corner_indices = [(0,0), (0,2), (2,0), (2,2)]

print("\n=== Neurons with POSITIVE corner response AND positive fc_weight ===")
for c_idx, c_name in enumerate(corner_names):
    ci, cj = corner_indices[c_idx]
    print(f"\n{c_name} corner:")
    for class_idx in range(10):
        candidates = []
        for n in range(64):
            spatial = conv3_w[n].sum(axis=0)
            corner_val = spatial[ci, cj]
            if corner_val > 1.5 and fc_w[class_idx, n] > 0.2:
                candidates.append((n, fc_w[class_idx, n], corner_val, conv3_bias[n]))
        if candidates:
            candidates.sort(key=lambda x: x[1] * x[2], reverse=True)  # fc_weight * corner_val
            print(f"  Class {class_idx} ({CLASSES[class_idx]}):")
            for n, fc_val, corner_val, bias in candidates[:5]:
                print(f"    Neuron {n}: fc_w={fc_val:.3f}, corner={corner_val:.3f}, bias={bias:.3f}, product={fc_val*corner_val:.3f}")

print("\n=== Neurons with NEGATIVE corner response AND negative fc_weight (suppression helps) ===")
for c_idx, c_name in enumerate(corner_names):
    ci, cj = corner_indices[c_idx]
    print(f"\n{c_name} corner:")
    for class_idx in range(10):
        candidates = []
        for n in range(64):
            spatial = conv3_w[n].sum(axis=0)
            corner_val = spatial[ci, cj]
            if corner_val < -1.5 and fc_w[class_idx, n] < -0.2:
                candidates.append((n, fc_w[class_idx, n], corner_val, conv3_bias[n]))
        if candidates:
            candidates.sort(key=lambda x: x[1] * x[2], reverse=True)  # fc_weight * corner_val (both neg = pos)
            print(f"  Class {class_idx} ({CLASSES[class_idx]}):")
            for n, fc_val, corner_val, bias in candidates[:5]:
                print(f"    Neuron {n}: fc_w={fc_val:.3f}, corner={corner_val:.3f}, bias={bias:.3f}, product={fc_val*corner_val:.3f}")
